import test from 'node:test';import assert from 'node:assert/strict';import {validateLimit} from './backend-limit.mjs';
test('valid bounded integer',()=>assert.equal(validateLimit(4),true));
test('reject fractional backend pagination',()=>assert.equal(validateLimit(1.5),false));
test('reject excessive backend pagination',()=>assert.equal(validateLimit(101),false));
test('reject strings and infinity',()=>{assert.equal(validateLimit('4'),false);assert.equal(validateLimit(Infinity),false);});
